contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, uint v2) public payable {
        // Set MinSum before initialization.
        c.SetMinSum(v1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {} else {}

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(v2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.MinSum() == v1);
    }

    receive() external payable {}
}

